Catalog.Register("semantic.world.alarm.react", {
    variants = {
        v("semantic.world.alarm.react.house_alarm_open", "hoomans.world.alarm.react.house_alarm_open", "Damn—house alarm! Every {noun.zombie} on this {noun.road} is going to hear that!", { combatReactionRole = "house_alarm_open" }, 8, true),
        v("semantic.world.alarm.react.house_alarm_open_2", "hoomans.world.alarm.react.house_alarm_open_2", "Shit, a burglar alarm! {addressee.name}, we need to move before the whole block swarms in!", { combatReactionRole = "house_alarm_open" }, 8, true),
        v("semantic.world.alarm.react.house_alarm_open_3", "hoomans.world.alarm.react.house_alarm_open_3", "There goes a house alarm—great, like we needed a dinner bell ringing!", { combatReactionRole = "house_alarm_open" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_open_4", "hoomans.world.alarm.react.house_alarm_open_4", "Hear that siren? Somebody tripped a security system nearby—weapons ready!", { combatReactionRole = "house_alarm_open" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_open_5", "hoomans.world.alarm.react.house_alarm_open_5", "Loud alarm going off! Don't linger around here, {addressee.name}!", { combatReactionRole = "house_alarm_open" }, 8, true),
        v("semantic.world.alarm.react.house_alarm_reply", "hoomans.world.alarm.react.house_alarm_reply", "Yeah, let's get clear before {noun.pack|a} shows up!", { combatReactionRole = "house_alarm_reply" }, 8, true),
        v("semantic.world.alarm.react.house_alarm_reply_2", "hoomans.world.alarm.react.house_alarm_reply_2", "Copy that, {addressee.name}—eyes on the corners, they'll be pouring in any second.", { combatReactionRole = "house_alarm_reply" }, 8, true),
        v("semantic.world.alarm.react.house_alarm_reply_3", "hoomans.world.alarm.react.house_alarm_reply_3", "Way too loud. Keep tight and let's put some distance between us and that house.", { combatReactionRole = "house_alarm_reply" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_reply_4", "hoomans.world.alarm.react.house_alarm_reply_4", "I hear it—stay sharp and don't let them box us in!", { combatReactionRole = "house_alarm_reply" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_reply_5", "hoomans.world.alarm.react.house_alarm_reply_5", "No point fighting a whole neighborhood over an alarm. Let's stay mobile.", { combatReactionRole = "house_alarm_reply" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_chime_1", "hoomans.world.alarm.react.house_alarm_chime_1", "Got your back—watching the rear in case stragglers come through.", { combatReactionRole = "house_alarm_chime" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_chime_2", "hoomans.world.alarm.react.house_alarm_chime_2", "Just my luck. Keep moving, I'm right behind you.", { combatReactionRole = "house_alarm_chime" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_chime_3", "hoomans.world.alarm.react.house_alarm_chime_3", "Stay off the main street if we can—that noise carries for blocks.", { combatReactionRole = "house_alarm_chime" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_chime_4", "hoomans.world.alarm.react.house_alarm_chime_4", "Ready if anything jumps out. Let's not hang around.", { combatReactionRole = "house_alarm_chime" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_ended_open_1", "hoomans.world.alarm.react.house_alarm_ended_open_1", "Finally—that alarm cut out. My ears are still ringing.", { combatReactionRole = "house_alarm_ended_open" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_ended_open_2", "hoomans.world.alarm.react.house_alarm_ended_open_2", "Alarm's dead, {addressee.name}, but the damage is done—stay alert for stragglers.", { combatReactionRole = "house_alarm_ended_open" }, 8, true),
        v("semantic.world.alarm.react.house_alarm_ended_open_3", "hoomans.world.alarm.react.house_alarm_ended_open_3", "Thank god that siren shut off. Watch the treeline—anything nearby is still headed this way.", { combatReactionRole = "house_alarm_ended_open" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_ended_open_4", "hoomans.world.alarm.react.house_alarm_ended_open_4", "Quiet again... don't let your guard down yet, the dead take a minute to arrive.", { combatReactionRole = "house_alarm_ended_open" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_ended_reply_1", "hoomans.world.alarm.react.house_alarm_ended_reply_1", "Yeah, silence after an alarm is never really safe. Keeping my eyes peeled.", { combatReactionRole = "house_alarm_ended_reply" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_ended_reply_2", "hoomans.world.alarm.react.house_alarm_ended_reply_2", "Agreed, {addressee.name}. Let's check our sightlines before we relax.", { combatReactionRole = "house_alarm_ended_reply" }, 8, true),
        v("semantic.world.alarm.react.house_alarm_ended_reply_3", "hoomans.world.alarm.react.house_alarm_ended_reply_3", "At least I can hear myself think again. Still watching the perimeter.", { combatReactionRole = "house_alarm_ended_reply" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_ended_reply_4", "hoomans.world.alarm.react.house_alarm_ended_reply_4", "Stay ready—half the neighborhood probably started shambling over here.", { combatReactionRole = "house_alarm_ended_reply" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_ended_chime_1", "hoomans.world.alarm.react.house_alarm_ended_chime_1", "Looks clear on my side for now, let's keep it that way.", { combatReactionRole = "house_alarm_ended_chime" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_ended_chime_2", "hoomans.world.alarm.react.house_alarm_ended_chime_2", "If we're lucky they went straight for that house instead of us.", { combatReactionRole = "house_alarm_ended_chime" }, 8, false),
        v("semantic.world.alarm.react.house_alarm_ended_chime_3", "hoomans.world.alarm.react.house_alarm_ended_chime_3", "Good—now let's breathe and keep moving smart.", { combatReactionRole = "house_alarm_ended_chime" }, 8, false),
        v("semantic.world.alarm.react.default", "hoomans.world.alarm.react.default", "That alarm is going to draw trouble—stay sharp!", nil, 5, false),
    },
})

Catalog.Register("semantic.world.chopper.react", {
    variants = {
        v("semantic.world.chopper.react.chopper_start_open_1", "hoomans.world.chopper.react.chopper_start_open_1", "Chopper! Hear those blades, {addressee.name}? Get under a roof right now!", { combatReactionRole = "chopper_start_open" }, 8, true),
        v("semantic.world.chopper.react.chopper_start_open_2", "hoomans.world.chopper.react.chopper_start_open_2", "Damn—helicopter overhead! It's going to drag every dead one in the county right onto us!", { combatReactionRole = "chopper_start_open" }, 8, false),
        v("semantic.world.chopper.react.chopper_start_open_3", "hoomans.world.chopper.react.chopper_start_open_3", "Wait—rotor blades! Everybody get indoors and stay away from the windows!", { combatReactionRole = "chopper_start_open" }, 8, false),
        v("semantic.world.chopper.react.chopper_start_open_4", "hoomans.world.chopper.react.chopper_start_open_4", "Chopper inbound! Don't let it spot us in the open, {addressee.name}!", { combatReactionRole = "chopper_start_open" }, 8, true),
        v("semantic.world.chopper.react.chopper_start_open_5", "hoomans.world.chopper.react.chopper_start_open_5", "That's a helicopter—and it sure isn't here to rescue us. Find cover!", { combatReactionRole = "chopper_start_open" }, 8, false),
        v("semantic.world.chopper.react.chopper_start_reply_1", "hoomans.world.chopper.react.chopper_start_reply_1", "On it, {addressee.name}! Inside a building—now, before it hovers over us!", { combatReactionRole = "chopper_start_reply" }, 8, true),
        v("semantic.world.chopper.react.chopper_start_reply_2", "hoomans.world.chopper.react.chopper_start_reply_2", "I hear it! Keep low and get behind solid walls!", { combatReactionRole = "chopper_start_reply" }, 8, false),
        v("semantic.world.chopper.react.chopper_start_reply_3", "hoomans.world.chopper.react.chopper_start_reply_3", "Last thing we need is a horde following those rotors—move!", { combatReactionRole = "chopper_start_reply" }, 8, false),
        v("semantic.world.chopper.react.chopper_start_reply_4", "hoomans.world.chopper.react.chopper_start_reply_4", "Yeah, no waving at it—get out of sight and hunker down!", { combatReactionRole = "chopper_start_reply" }, 8, false),
        v("semantic.world.chopper.react.chopper_start_chime_1", "hoomans.world.chopper.react.chopper_start_chime_1", "Right behind you—close the doors once we're inside!", { combatReactionRole = "chopper_start_chime" }, 8, false),
        v("semantic.world.chopper.react.chopper_start_chime_2", "hoomans.world.chopper.react.chopper_start_chime_2", "Keep quiet once we're under cover and wait it out.", { combatReactionRole = "chopper_start_chime" }, 8, false),
        v("semantic.world.chopper.react.chopper_start_chime_3", "hoomans.world.chopper.react.chopper_start_chime_3", "Watch the streets—dead ones are already shifting toward the noise!", { combatReactionRole = "chopper_start_chime" }, 8, false),
        v("semantic.world.chopper.react.chopper_ended_open_1", "hoomans.world.chopper.react.chopper_ended_open_1", "Rotors are fading out... sounds like the chopper finally left.", { combatReactionRole = "chopper_ended_open" }, 8, false),
        v("semantic.world.chopper.react.chopper_ended_open_2", "hoomans.world.chopper.react.chopper_ended_open_2", "It's gone, {addressee.name}. Give it a second before we step outside—the streets will be messy.", { combatReactionRole = "chopper_ended_open" }, 8, true),
        v("semantic.world.chopper.react.chopper_ended_open_3", "hoomans.world.chopper.react.chopper_ended_open_3", "Chopper's finally moving off. Let's check the windows before we head back out.", { combatReactionRole = "chopper_ended_open" }, 8, false),
        v("semantic.world.chopper.react.chopper_ended_open_4", "hoomans.world.chopper.react.chopper_ended_open_4", "Thank god that noise is gone. Stay sharp—it probably stirred up half the town.", { combatReactionRole = "chopper_ended_open" }, 8, false),
        v("semantic.world.chopper.react.chopper_ended_reply_1", "hoomans.world.chopper.react.chopper_ended_reply_1", "Good call waiting a beat, {addressee.name}. Let's peek outside carefully.", { combatReactionRole = "chopper_ended_reply" }, 8, true),
        v("semantic.world.chopper.react.chopper_ended_reply_2", "hoomans.world.chopper.react.chopper_ended_reply_2", "Glad we kept our heads down. Weapons ready when we step out.", { combatReactionRole = "chopper_ended_reply" }, 8, false),
        v("semantic.world.chopper.react.chopper_ended_reply_3", "hoomans.world.chopper.react.chopper_ended_reply_3", "Yeah, that thing always leaves a mess of walkers behind. Stay tight.", { combatReactionRole = "chopper_ended_reply" }, 8, false),
        v("semantic.world.chopper.react.chopper_ended_reply_4", "hoomans.world.chopper.react.chopper_ended_reply_4", "Looks like we rode it out. Let's see what's still shambling around.", { combatReactionRole = "chopper_ended_reply" }, 8, false),
        v("semantic.world.chopper.react.chopper_ended_chime_1", "hoomans.world.chopper.react.chopper_ended_chime_1", "My heart's still pounding. Good thing we got under cover.", { combatReactionRole = "chopper_ended_chime" }, 8, false),
        v("semantic.world.chopper.react.chopper_ended_chime_2", "hoomans.world.chopper.react.chopper_ended_chime_2", "Next time I hear blades, I'm not even looking up—straight indoors.", { combatReactionRole = "chopper_ended_chime" }, 8, false),
        v("semantic.world.chopper.react.chopper_ended_chime_3", "hoomans.world.chopper.react.chopper_ended_chime_3", "Alright, back to business—watch the corners.", { combatReactionRole = "chopper_ended_chime" }, 8, false),
        v("semantic.world.chopper.react.default", "hoomans.world.chopper.react.default", "Helicopter noise—keep low and stay under cover!", nil, 5, false),
    },
})

