Catalog.Register("semantic.world.media.broadcast", {
    variants = {
        v("semantic.world.media.broadcast.aebs_air_activity_open_1", "hoomans.world.media.broadcast.aebs_air_activity_open_1", "Hold up, {addressee.name}! Did you catch {slot.broadcast.episode} on {slot.broadcast.channel}? Air activity detected means a chopper is coming!", { combatReactionRole = "aebs_air_activity_open" }, 12, true),
        v("semantic.world.media.broadcast.aebs_air_activity_open_2", "hoomans.world.media.broadcast.aebs_air_activity_open_2", "Listen to {slot.broadcast.channel}, {addressee.name}! Air activity warning. We need a solid roof nearby today.", { combatReactionRole = "aebs_air_activity_open" }, 12, true),
        v("semantic.world.media.broadcast.aebs_air_activity_reply_1", "hoomans.world.media.broadcast.aebs_air_activity_reply_1", "Yeah, I heard it, {addressee.name}. If that helicopter spots us in the open, it'll drag every walker in the county right on top of us.", { combatReactionRole = "aebs_air_activity_reply" }, 12, true),
        v("semantic.world.media.broadcast.aebs_air_activity_chime_1", "hoomans.world.media.broadcast.aebs_air_activity_chime_1", "Let's keep our runs short and stay close to buildings until it passes.", { combatReactionRole = "aebs_air_activity_chime" }, 12, false),
        v("semantic.world.media.broadcast.aebs_air_activity_wrap_1", "hoomans.world.media.broadcast.aebs_air_activity_wrap_1", "Good thing we had the emergency frequency tuned in. Stay sharp.", { combatReactionRole = "aebs_air_activity_wrap" }, 12, false),
        v("semantic.world.media.broadcast.aebs_power_warning_open_1", "hoomans.world.media.broadcast.aebs_power_warning_open_1", "Bad news on {slot.broadcast.channel}, {addressee.name}. {slot.broadcast.episode} says the power grid is starting to fail.", { combatReactionRole = "aebs_power_warning_open" }, 12, true),
        v("semantic.world.media.broadcast.aebs_power_warning_reply_1", "hoomans.world.media.broadcast.aebs_power_warning_reply_1", "Means the lights and fridges are on borrowed time, {addressee.name}. We should cook perishables and hunt for a generator.", { combatReactionRole = "aebs_power_warning_reply" }, 12, true),
        v("semantic.world.media.broadcast.aebs_power_warning_chime_1", "hoomans.world.media.broadcast.aebs_power_warning_chime_1", "Don't forget fuel cans and a manual if we find one. Dark nights are gonna get a lot rougher.", { combatReactionRole = "aebs_power_warning_chime" }, 12, false),
        v("semantic.world.media.broadcast.aebs_power_warning_wrap_1", "hoomans.world.media.broadcast.aebs_power_warning_wrap_1", "At least we got a heads-up before everything went dark.", { combatReactionRole = "aebs_power_warning_wrap" }, 12, false),
        v("semantic.world.media.broadcast.aebs_weather_warning_open_1", "hoomans.world.media.broadcast.aebs_weather_warning_open_1", "Catch that on {slot.broadcast.channel}, {addressee.name}? {slot.broadcast.episode} says rough weather is heading our way.", { combatReactionRole = "aebs_weather_warning_open" }, 11, true),
        v("semantic.world.media.broadcast.aebs_weather_warning_reply_1", "hoomans.world.media.broadcast.aebs_weather_warning_reply_1", "Appreciate the warning, {addressee.name}. Let's pack warm layers and plan a dry place to hole up.", { combatReactionRole = "aebs_weather_warning_reply" }, 11, true),
        v("semantic.world.media.broadcast.aebs_weather_warning_chime_1", "hoomans.world.media.broadcast.aebs_weather_warning_chime_1", "Fighting the dead in a storm is miserable. Better to be ready early.", { combatReactionRole = "aebs_weather_warning_chime" }, 11, false),
        v("semantic.world.media.broadcast.aebs_weather_warning_wrap_1", "hoomans.world.media.broadcast.aebs_weather_warning_wrap_1", "Keep that emergency channel handy, it's the only honest forecast left.", { combatReactionRole = "aebs_weather_warning_wrap" }, 11, false),
        v("semantic.world.media.broadcast.military_comms_open_1", "hoomans.world.media.broadcast.military_comms_open_1", "Shh, {addressee.name}, listen to {slot.broadcast.channel}. That's military traffic, and it doesn't sound like they're holding.", { combatReactionRole = "military_comms_open" }, 11, true),
        v("semantic.world.media.broadcast.military_comms_reply_1", "hoomans.world.media.broadcast.military_comms_reply_1", "If the army's falling back on {slot.broadcast.channel}, {addressee.name}, nobody's coming to rescue us.", { combatReactionRole = "military_comms_reply" }, 11, true),
        v("semantic.world.media.broadcast.military_comms_chime_1", "hoomans.world.media.broadcast.military_comms_chime_1", "At least now we know the truth instead of waiting for an evacuation that's never coming.", { combatReactionRole = "military_comms_chime" }, 11, false),
        v("semantic.world.media.broadcast.military_comms_wrap_1", "hoomans.world.media.broadcast.military_comms_wrap_1", "We rely on ourselves from here on out.", { combatReactionRole = "military_comms_wrap" }, 11, false),
        v("semantic.world.media.broadcast.survivor_radio_open_1", "hoomans.world.media.broadcast.survivor_radio_open_1", "Wait, {addressee.name}! Someone's talking on {slot.broadcast.channel}. There are still other people out there.", { combatReactionRole = "survivor_radio_open" }, 11, true),
        v("semantic.world.media.broadcast.survivor_radio_reply_1", "hoomans.world.media.broadcast.survivor_radio_reply_1", "Hard to tell how far away they are, {addressee.name}, or whether they're friendly.", { combatReactionRole = "survivor_radio_reply" }, 11, true),
