        v("semantic.world.media.broadcast.survivor_radio_wrap_1", "hoomans.world.media.broadcast.survivor_radio_wrap_1", "Keep listening, we might learn which roads are still clear.", { combatReactionRole = "survivor_radio_wrap" }, 11, false),
        v("semantic.world.media.broadcast.news_outbreak_open_1", "hoomans.world.media.broadcast.news_outbreak_open_1", "Look at {slot.broadcast.channel}, {addressee.name}. Hearing {slot.broadcast.topic} makes it feel all too real.", { combatReactionRole = "news_outbreak_open" }, 11, true),
        v("semantic.world.media.broadcast.news_outbreak_open_2", "hoomans.world.media.broadcast.news_outbreak_open_2", "Did you hear what {slot.broadcast.channel} just reported about {slot.broadcast.topic}, {addressee.name}? Things are falling apart fast.", { combatReactionRole = "news_outbreak_open" }, 11, true),
        v("semantic.world.media.broadcast.news_outbreak_reply_1", "hoomans.world.media.broadcast.news_outbreak_reply_1", "Half of what they're saying on {slot.broadcast.channel} is already behind what we've seen on the streets, {addressee.name}.", { combatReactionRole = "news_outbreak_reply" }, 11, true),
        v("semantic.world.media.broadcast.news_outbreak_chime_1", "hoomans.world.media.broadcast.news_outbreak_chime_1", "Still worth watching while the signal lasts. Any clue about what's happening outside Knox helps.", { combatReactionRole = "news_outbreak_chime" }, 11, false),
        v("semantic.world.media.broadcast.news_outbreak_wrap_1", "hoomans.world.media.broadcast.news_outbreak_wrap_1", "Yeah. Let's stay focused on surviving right here.", { combatReactionRole = "news_outbreak_wrap" }, 11, false),
        v("semantic.world.media.broadcast.news_general_open_1", "hoomans.world.media.broadcast.news_general_open_1", "Still getting a signal from {slot.broadcast.channel}, {addressee.name}. Let's see what they're saying.", { combatReactionRole = "news_general_open" }, 10, true),
        v("semantic.world.media.broadcast.news_general_reply_1", "hoomans.world.media.broadcast.news_general_reply_1", "Good call, {addressee.name}. Never know when something actually useful slips through.", { combatReactionRole = "news_general_reply" }, 10, true),
        v("semantic.world.media.broadcast.news_general_chime_1", "hoomans.world.media.broadcast.news_general_chime_1", "Just keep the volume reasonable so we don't draw company.", { combatReactionRole = "news_general_chime" }, 10, false),
        v("semantic.world.media.broadcast.news_general_wrap_1", "hoomans.world.media.broadcast.news_general_wrap_1", "Fair point. Ears open.", { combatReactionRole = "news_general_wrap" }, 10, false),
        v("semantic.world.media.broadcast.tv_watching_life_and_living_open", "hoomans.world.media.broadcast.tv_watching_life_and_living_open", "Catching {slot.show.name} on {slot.broadcast.channel}, {addressee.name}. Might actually pick up something useful.", { combatReactionRole = "tv_watching_life_and_living_open" }, 10, true),
        v("semantic.world.media.broadcast.tv_watching_life_and_living_reply", "hoomans.world.media.broadcast.tv_watching_life_and_living_reply", "Smart move, {addressee.name}. {slot.show.name} always has practical tips we can use out here.", { combatReactionRole = "tv_watching_life_and_living_reply" }, 10, true),
        v("semantic.world.media.broadcast.tv_watching_life_and_living_chime", "hoomans.world.media.broadcast.tv_watching_life_and_living_chime", "Take notes while we still have power. Half of survival is knowing how to fix and build things.", { combatReactionRole = "tv_watching_life_and_living_chime" }, 10, false),
        v("semantic.world.media.broadcast.tv_watching_life_and_living_wrap", "hoomans.world.media.broadcast.tv_watching_life_and_living_wrap", "Beats learning the hard way, that's for sure.", { combatReactionRole = "tv_watching_life_and_living_wrap" }, 10, false),
        v("semantic.world.media.broadcast.home_vhs_open_1", "hoomans.world.media.broadcast.home_vhs_open_1", "Whoa... {slot.show.name} is somebody's home tape, {addressee.name}. Feels strange peeking into their old life.", { combatReactionRole = "home_vhs_open" }, 10, true),
        v("semantic.world.media.broadcast.home_vhs_reply_1", "hoomans.world.media.broadcast.home_vhs_reply_1", "Yeah, {addressee.name}. Makes you wonder if they made it out alright.", { combatReactionRole = "home_vhs_reply" }, 10, true),
        v("semantic.world.media.broadcast.home_vhs_chime_1", "hoomans.world.media.broadcast.home_vhs_chime_1", "Hard to believe how normal everything looked just weeks ago.", { combatReactionRole = "home_vhs_chime" }, 10, false),
        v("semantic.world.media.broadcast.home_vhs_wrap_1", "hoomans.world.media.broadcast.home_vhs_wrap_1", "Let's keep moving when we're done. Don't want to get lost in the past.", { combatReactionRole = "home_vhs_wrap" }, 10, false),
        v("semantic.world.media.broadcast.music_radio_open_1", "hoomans.world.media.broadcast.music_radio_open_1", "Hey, {slot.show.name} is playing, {addressee.name}. Forgot how good a little music feels.", { combatReactionRole = "music_radio_open" }, 10, true),
        v("semantic.world.media.broadcast.music_radio_reply_1", "hoomans.world.media.broadcast.music_radio_reply_1", "No kidding, {addressee.name}. Beats listening to groaning walkers all day.", { combatReactionRole = "music_radio_reply" }, 10, true),
        v("semantic.world.media.broadcast.music_radio_chime_1", "hoomans.world.media.broadcast.music_radio_chime_1", "Just don't crank it so loud the whole neighborhood dances over here.", { combatReactionRole = "music_radio_chime" }, 10, false),
        v("semantic.world.media.broadcast.music_radio_wrap_1", "hoomans.world.media.broadcast.music_radio_wrap_1", "Hah, deal. Low volume, high morale.", { combatReactionRole = "music_radio_wrap" }, 10, false),
        v("semantic.world.media.broadcast.tv_watching_show_open", "hoomans.world.media.broadcast.tv_watching_show_open", "Keeping an eye on {slot.show.name}, {addressee.name}. Feels surreal watching TV like nothing happened.", { combatReactionRole = "tv_watching_show_open" }, 9, true),
        v("semantic.world.media.broadcast.tv_watching_show_reply", "hoomans.world.media.broadcast.tv_watching_show_reply", "Honestly, {addressee.name}, five minutes of {slot.show.name} is a nice break from reality.", { combatReactionRole = "tv_watching_show_reply" }, 9, true),
        v("semantic.world.media.broadcast.tv_watching_show_chime", "hoomans.world.media.broadcast.tv_watching_show_chime", "Enjoy it while the signal holds. Won't last forever.", { combatReactionRole = "tv_watching_show_chime" }, 9, false),
        v("semantic.world.media.broadcast.tv_watching_show_wrap", "hoomans.world.media.broadcast.tv_watching_show_wrap", "True enough. Let's catch our breath and stay ready.", { combatReactionRole = "tv_watching_show_wrap" }, 9, false),
        v("semantic.world.media.broadcast.ob_looter_open_1", "hoomans.world.media.broadcast.ob_looter_open_1", "Don't buy a word of that broadcast, {addressee.name}. Free supplies and 'come alone' screams ambush.", { combatReactionRole = "open_band_looter_trap_open" }, 12, true),
        v("semantic.world.media.broadcast.ob_looter_reply_1", "hoomans.world.media.broadcast.ob_looter_reply_1", "Yeah, {addressee.name}, nobody hands out free food to strangers out here unless they're setting a trap.", { combatReactionRole = "open_band_looter_trap_reply" }, 12, true),
        v("semantic.world.media.broadcast.ob_looter_chime_1", "hoomans.world.media.broadcast.ob_looter_chime_1", "If we ever go near them, we go armed and we don't walk in blind.", { combatReactionRole = "open_band_looter_trap_chime" }, 12, false),
        v("semantic.world.media.broadcast.ob_looter_wrap_1", "hoomans.world.media.broadcast.ob_looter_wrap_1", "Agreed. Keep our distance unless we're ready for a fight.", { combatReactionRole = "open_band_looter_trap_wrap" }, 12, false),
        v("semantic.world.media.broadcast.ob_trader_open_1", "hoomans.world.media.broadcast.ob_trader_open_1", "Did you hear that on {slot.broadcast.channel}, {addressee.name}? Sounds like a trader caravan is passing through.", { combatReactionRole = "open_band_trader_open" }, 12, true),
        v("semantic.world.media.broadcast.ob_trader_reply_1", "hoomans.world.media.broadcast.ob_trader_reply_1", "Could be worth checking out, {addressee.name}. Extra tools, batteries, or medicine are hard to come by.", { combatReactionRole = "open_band_trader_reply" }, 12, true),
        v("semantic.world.media.broadcast.ob_trader_chime_1", "hoomans.world.media.broadcast.ob_trader_chime_1", "Let's check what we can spare to barter before we head their way.", { combatReactionRole = "open_band_trader_chime" }, 12, false),
        v("semantic.world.media.broadcast.ob_trader_wrap_1", "hoomans.world.media.broadcast.ob_trader_wrap_1", "Good call. Keep weapons slung, stay polite, and watch their hands.", { combatReactionRole = "open_band_trader_wrap" }, 12, false),
        v("semantic.world.media.broadcast.ob_refugee_open_1", "hoomans.world.media.broadcast.ob_refugee_open_1", "Rough call on {slot.broadcast.channel}, {addressee.name}. Sounds like a group of wounded refugees asking for help.", { combatReactionRole = "open_band_refugee_open" }, 12, true),
        v("semantic.world.media.broadcast.ob_refugee_reply_1", "hoomans.world.media.broadcast.ob_refugee_reply_1", "Hate hearing families stuck out there like that, {addressee.name}. If we can spare medicine, maybe we should look for them.", { combatReactionRole = "open_band_refugee_reply" }, 12, true),
        v("semantic.world.media.broadcast.ob_refugee_chime_1", "hoomans.world.media.broadcast.ob_refugee_chime_1", "Just be careful if we go. Desperate people can still get spooked easily.", { combatReactionRole = "open_band_refugee_chime" }, 12, false),
        v("semantic.world.media.broadcast.ob_refugee_wrap_1", "hoomans.world.media.broadcast.ob_refugee_wrap_1", "Fair point. If we help them, we approach slow and announce ourselves.", { combatReactionRole = "open_band_refugee_wrap" }, 12, false),
        v("semantic.world.media.broadcast.ob_settle_open_1", "hoomans.world.media.broadcast.ob_settle_open_1", "Whoa, listen to {slot.broadcast.channel}, {addressee.name}. Sounds like a real settlement with a working perimeter.", { combatReactionRole = "open_band_settlement_open" }, 12, true),
        v("semantic.world.media.broadcast.ob_settle_reply_1", "hoomans.world.media.broadcast.ob_settle_reply_1", "They sounded serious about identifying ourselves on approach, {addressee.name}. At least they're organized.", { combatReactionRole = "open_band_settlement_reply" }, 12, true),
        v("semantic.world.media.broadcast.ob_settle_chime_1", "hoomans.world.media.broadcast.ob_settle_chime_1", "Knowing there's an enclave holding out nearby gives us options if we need allies.", { combatReactionRole = "open_band_settlement_chime" }, 12, false),
        v("semantic.world.media.broadcast.ob_settle_wrap_1", "hoomans.world.media.broadcast.ob_settle_wrap_1", "Let's remember where they're broadcasting from. Could come in handy.", { combatReactionRole = "open_band_settlement_wrap" }, 12, false),
        v("semantic.world.media.broadcast.ob_conflict_open_1", "hoomans.world.media.broadcast.ob_conflict_open_1", "Hah, listen to them going at each other on {slot.broadcast.channel}, {addressee.name}. Even the apocalypse doesn't stop people from bickering.", { combatReactionRole = "open_band_conflict_open" }, 11, true),
        v("semantic.world.media.broadcast.ob_conflict_reply_1", "hoomans.world.media.broadcast.ob_conflict_reply_1", "Sounds like rival groups fighting over supplies, {addressee.name}. Better them than us.", { combatReactionRole = "open_band_conflict_reply" }, 11, true),
        v("semantic.world.media.broadcast.ob_conflict_chime_1", "hoomans.world.media.broadcast.ob_conflict_chime_1", "At least they're broadcasting their drama so we know who to steer clear of.", { combatReactionRole = "open_band_conflict_chime" }, 11, false),
        v("semantic.world.media.broadcast.ob_conflict_wrap_1", "hoomans.world.media.broadcast.ob_conflict_wrap_1", "Yeah. Let's stay out of their crossfire.", { combatReactionRole = "open_band_conflict_wrap" }, 11, false),
        v("semantic.world.media.broadcast.num_stat_open_1", "hoomans.world.media.broadcast.num_stat_open_1", "What the hell is that on {slot.broadcast.channel}, {addressee.name}? Just numbers and callsigns repeating...", { combatReactionRole = "numbers_station_open" }, 12, true),
        v("semantic.world.media.broadcast.num_stat_reply_1", "hoomans.world.media.broadcast.num_stat_reply_1", "Gives me the creeps, {addressee.name}. Either it's an automated military loop or somebody's still sending coded orders.", { combatReactionRole = "numbers_station_reply" }, 12, true),
        v("semantic.world.media.broadcast.num_stat_chime_1", "hoomans.world.media.broadcast.num_stat_chime_1", "Whatever it is, it's not meant for regular folks like us.", { combatReactionRole = "numbers_station_chime" }, 12, false),
        v("semantic.world.media.broadcast.num_stat_wrap_1", "hoomans.world.media.broadcast.num_stat_wrap_1", "Yeah, let's tune past it before it gets in my head.", { combatReactionRole = "numbers_station_wrap" }, 12, false),
        v("semantic.world.media.broadcast.cann_rad_open_1", "hoomans.world.media.broadcast.cann_rad_open_1", "Turn that down, {addressee.name}... did you hear how they were talking about people on {slot.broadcast.channel}?", { combatReactionRole = "cannibal_radio_open" }, 12, true),
        v("semantic.world.media.broadcast.cann_rad_reply_1", "hoomans.world.media.broadcast.cann_rad_reply_1", "That made my stomach turn, {addressee.name}. Some folks lost their humanity way faster than the dead did.", { combatReactionRole = "cannibal_radio_reply" }, 12, true),
        v("semantic.world.media.broadcast.cann_rad_chime_1", "hoomans.world.media.broadcast.cann_rad_chime_1", "We ever run into people like that, we don't hesitate. Keep our guard up.", { combatReactionRole = "cannibal_radio_chime" }, 12, false),
        v("semantic.world.media.broadcast.cann_rad_wrap_1", "hoomans.world.media.broadcast.cann_rad_wrap_1", "Stay close to each other. The dead aren't the only monsters out here.", { combatReactionRole = "cannibal_radio_wrap" }, 12, false),
        v("semantic.world.media.broadcast.past_rad_open_1", "hoomans.world.media.broadcast.past_rad_open_1", "Listen to that preacher on {slot.broadcast.channel}, {addressee.name}. Guy's still broadcasting sermons into the void.", { combatReactionRole = "pastor_radio_open" }, 11, true),
        v("semantic.world.media.broadcast.past_rad_reply_1", "hoomans.world.media.broadcast.past_rad_reply_1", "Can't blame people for looking for meaning when the whole world collapses, {addressee.name}.", { combatReactionRole = "pastor_radio_reply" }, 11, true),
        v("semantic.world.media.broadcast.past_rad_chime_1", "hoomans.world.media.broadcast.past_rad_chime_1", "Faith is fine, just as long as we keep our blades sharp too.", { combatReactionRole = "pastor_radio_chime" }, 11, false),
        v("semantic.world.media.broadcast.past_rad_wrap_1", "hoomans.world.media.broadcast.past_rad_wrap_1", "Amen to that. Let's stay practical.", { combatReactionRole = "pastor_radio_wrap" }, 11, false),
        v("semantic.world.media.broadcast.default", "hoomans.world.media.broadcast.default", "Still catching a signal on that broadcast.", nil, 5, false),
    },
})

Catalog.Register("semantic.progression.level_up", {
    variants = {
        v("semantic.progression.level_up.tv_lvl_open_1", "hoomans.progression.level_up.tv_lvl_open_1", "Hey {addressee.name}, watching {slot.show.name} actually clicked! I feel like I finally get {slot.skill.name} now.", { combatReactionRole = "tv_broadcast_open" }, 12, true),
        v("semantic.progression.level_up.tv_lvl_open_2", "hoomans.progression.level_up.tv_lvl_open_2", "Didn't expect {slot.show.name} to teach me this much, {addressee.name}. My {slot.skill.name} just jumped up a notch.", { combatReactionRole = "tv_broadcast_open" }, 12, true),
        v("semantic.progression.level_up.tv_lvl_reply_1", "hoomans.progression.level_up.tv_lvl_reply_1", "Nice work, {addressee.name}! Good thing we caught that episode while the signal lasted.", { combatReactionRole = "tv_broadcast_reply" }, 12, true),
        v("semantic.progression.level_up.tv_lvl_chime_1", "hoomans.progression.level_up.tv_lvl_chime_1", "Keep watching whenever we get the chance. Every bit of {slot.skill.name} helps the whole crew.", { combatReactionRole = "tv_broadcast_chime" }, 12, true),
        v("semantic.progression.level_up.combat_lvl_open_1", "hoomans.progression.level_up.combat_lvl_open_1", "Getting a much better feel for {slot.skill.name}, {addressee.name}. Those fights are sharpening my instincts.", { combatReactionRole = "combat_open" }, 12, true),
        v("semantic.progression.level_up.combat_lvl_open_2", "hoomans.progression.level_up.combat_lvl_open_2", "That last scrap taught me a thing or two about {slot.skill.name}, {addressee.name}. Feeling steadier already.", { combatReactionRole = "combat_open" }, 12, true),
        v("semantic.progression.level_up.combat_lvl_reply_1", "hoomans.progression.level_up.combat_lvl_reply_1", "I noticed, {addressee.name}. You're handling yourself way cleaner out there.", { combatReactionRole = "combat_reply" }, 12, true),
        v("semantic.progression.level_up.combat_lvl_chime_1", "hoomans.progression.level_up.combat_lvl_chime_1", "Good to hear. Stronger hands in a fight keep all of us breathing.", { combatReactionRole = "combat_chime" }, 12, false),
        v("semantic.progression.level_up.build_lvl_open_1", "hoomans.progression.level_up.build_lvl_open_1", "Hah, check that out, {addressee.name}! All this hands-on work is really paying off with my {slot.skill.name}.", { combatReactionRole = "building_open" }, 12, true),
        v("semantic.progression.level_up.build_lvl_open_2", "hoomans.progression.level_up.build_lvl_open_2", "Finally getting the hang of {slot.skill.name}, {addressee.name}. My joints and cuts are coming together way cleaner.", { combatReactionRole = "building_open" }, 12, true),
        v("semantic.progression.level_up.build_lvl_reply_1", "hoomans.progression.level_up.build_lvl_reply_1", "Looking solid, {addressee.name}. Having someone good at {slot.skill.name} is huge for our camp.", { combatReactionRole = "building_reply" }, 12, true),
        v("semantic.progression.level_up.build_lvl_chime_1", "hoomans.progression.level_up.build_lvl_chime_1", "Keep at it. Better walls and gear mean safer nights.", { combatReactionRole = "building_chime" }, 12, false),
        v("semantic.progression.level_up.ex_lvl_open_1", "hoomans.progression.level_up.ex_lvl_open_1", "Whew... pushing myself is finally paying off, {addressee.name}. My {slot.skill.name} feels noticeably stronger.", { combatReactionRole = "exercise_open" }, 12, true),
        v("semantic.progression.level_up.ex_lvl_open_2", "hoomans.progression.level_up.ex_lvl_open_2", "All that training is starting to show, {addressee.name}. Definitely leveled up my {slot.skill.name}.", { combatReactionRole = "exercise_open" }, 12, true),
        v("semantic.progression.level_up.ex_lvl_reply_1", "hoomans.progression.level_up.ex_lvl_reply_1", "Way to stick with it, {addressee.name}. Outrunning a horde is half the battle.", { combatReactionRole = "exercise_reply" }, 12, true),
        v("semantic.progression.level_up.ex_lvl_chime_1", "hoomans.progression.level_up.ex_lvl_chime_1", "Might have to join your routine before I fall behind.", { combatReactionRole = "exercise_chime" }, 12, false),
        v("semantic.progression.level_up.cook_lvl_open_1", "hoomans.progression.level_up.cook_lvl_open_1", "I'm getting the hang of {slot.skill.name}, {addressee.name}. Can actually make scavenged food taste decent now.", { combatReactionRole = "cooking_open" }, 12, true),
        v("semantic.progression.level_up.cook_lvl_reply_1", "hoomans.progression.level_up.cook_lvl_reply_1", "Now that's the best news I've heard all week, {addressee.name}.", { combatReactionRole = "cooking_reply" }, 12, true),
        v("semantic.progression.level_up.cook_lvl_chime_1", "hoomans.progression.level_up.cook_lvl_chime_1", "A hot meal does wonders for morale out here.", { combatReactionRole = "cooking_chime" }, 12, false),
        v("semantic.progression.level_up.med_lvl_open_1", "hoomans.progression.level_up.med_lvl_open_1", "My hands are getting steadier with {slot.skill.name}, {addressee.name}. Patching wounds feels second nature now.", { combatReactionRole = "medical_open" }, 12, true),
        v("semantic.progression.level_up.med_lvl_reply_1", "hoomans.progression.level_up.med_lvl_reply_1", "Glad to have you on our side, {addressee.name}. Good medical hands save lives.", { combatReactionRole = "medical_reply" }, 12, true),
        v("semantic.progression.level_up.med_lvl_chime_1", "hoomans.progression.level_up.med_lvl_chime_1", "Hopefully we won't need it often, but it's reassuring knowing you've got us covered.", { combatReactionRole = "medical_chime" }, 12, false),
        v("semantic.progression.level_up.surv_lvl_open_1", "hoomans.progression.level_up.surv_lvl_open_1", "Starting to get a real knack for {slot.skill.name}, {addressee.name}. Practical experience beats everything.", { combatReactionRole = "survival_open" }, 12, true),
        v("semantic.progression.level_up.surv_lvl_reply_1", "hoomans.progression.level_up.surv_lvl_reply_1", "Nice, {addressee.name}. That's going to keep us self-sufficient out here.", { combatReactionRole = "survival_reply" }, 12, true),
        v("semantic.progression.level_up.surv_lvl_chime_1", "hoomans.progression.level_up.surv_lvl_chime_1", "Every new trick we learn buys us another week.", { combatReactionRole = "survival_chime" }, 12, false),
        v("semantic.progression.level_up.read_lvl_open_1", "hoomans.progression.level_up.read_lvl_open_1", "That book actually made {slot.skill.name} click, {addressee.name}. Makes way more sense now.", { combatReactionRole = "reading_open" }, 12, true),
        v("semantic.progression.level_up.read_lvl_reply_1", "hoomans.progression.level_up.read_lvl_reply_1", "Good stuff, {addressee.name}. Knowledge doesn't weigh down a backpack.", { combatReactionRole = "reading_reply" }, 12, true),
        v("semantic.progression.level_up.read_lvl_chime_1", "hoomans.progression.level_up.read_lvl_chime_1", "Let's grab any more manuals we spot on supply runs.", { combatReactionRole = "reading_chime" }, 12, false),
        v("semantic.progression.level_up.gen_lvl_open_1", "hoomans.progression.level_up.gen_lvl_open_1", "I think I'm really improving at {slot.skill.name}, {addressee.name}. Practice is paying off.", { combatReactionRole = "general_open" }, 10, true),
        v("semantic.progression.level_up.gen_lvl_reply_1", "hoomans.progression.level_up.gen_lvl_reply_1", "Good job, {addressee.name}. Every bit of skill counts out here.", { combatReactionRole = "general_reply" }, 10, true),
        v("semantic.progression.level_up.gen_lvl_chime_1", "hoomans.progression.level_up.gen_lvl_chime_1", "Keep it up, we're getting stronger as a group.", { combatReactionRole = "general_chime" }, 10, false),
        v("semantic.progression.level_up.default", "hoomans.progression.level_up.default", "Feels like I'm getting better at {slot.skill.name} every day.", nil, 5, true),
    },
})

Catalog.Register("semantic.world.weather.rain", {
    variants = {
        v("semantic.world.weather.rain.weather_rain_open", "hoomans.world.weather.rain.weather_rain_open", "Rain's picking up, {addressee.name}. {?clause.rain_note}", { combatReactionRole = "weather_rain_open" }, 8, true),
        v("semantic.world.weather.rain.weather_rain_reply", "hoomans.world.weather.rain.weather_rain_reply", "Yeah, {addressee.name}, let's keep dry and watch our footing.", { combatReactionRole = "weather_rain_reply" }, 8, true),
